!function(){var e=window.location.hash.substring(1);try{history.replaceState(null,"",window.location.pathname+window.location.search)}catch{}Office.onReady(function(){if(e)try{var t=decodeURIComponent(e),a=JSON.parse(t);Office.context.ui.messageParent(JSON.stringify(a))}catch(e){Office.context.ui.messageParent(JSON.stringify({error:"Failed to parse auth response: "+e.message}))}else Office.context.ui.messageParent(JSON.stringify({error:"No data received from auth dialog."}))})}();